head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.skw = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox_01(panel_1);
        $c.cm.PanelToGroupBox_02(panel_2);
        const sbmOptions = {
            id : "sbm_dts_jongmok",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_jongmok=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        await scwin.listSync2();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00009.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_jongmok_OnLoadCompleted
 * @description dts_jongmok 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_jongmok_OnLoadCompleted = function(rowcount) {
};

/**
 * @method
 * @name grd_jongmok_OnKeyPress
 * @description grd jongmok On Key Press 처리
 * @param {*} kcode kcode
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_jongmok_OnKeyPress = async function(kcode) {
    try {
        if (kcode === '13') {
            await scwin.Confirm();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00009.grd_jongmok_OnKeyPress" });
    }
};

/**
 * @method
 * @name grd_jongmok_OnDblClick
 * @description grd_jongmok 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_jongmok_OnDblClick = async function(row, colid) {
    try {
        await scwin.Confirm();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00009.grd_jongmok_OnDblClick" });
    }
};

/**
 * @method
 * @name img_search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_search_onclick = function() {
    try {
        scwin.JongmokName(txb_jongmokName.getValue());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00009.img_search_onclick" });
    }
};

/**
 * @method
 * @name txb_jongmokName_onkeydown
 * @description txb_jongmokName 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_jongmokName_onkeydown = function() {
    try {
        if (window.event.keyCode === "13") {
            scwin.JongmokName(window.event.keyCode);
            // JongmokSearch();

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00009.txb_jongmokName_onkeydown" });
