/**
 * @method
 * @name dts_jongmok_OnFilter
 * @description jongmok On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_jongmok_OnFilter = function(row) {
    try {
        if (scwin.skw !== "") {
            f1 = dts_jongmok.getCellData(row, "COM_ABBRV");
            f2 = dts_jongmok.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(scwin.skw) !== -1) {
                return true;
            } else if (f2.indexOf(scwin.skw) !== -1) {
                return true;
            } else {
                return false;
            }
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00009.dts_jongmok_OnFilter" });
    }
};

