///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name Jongmok
 * @description 가나다라..검색
 * @param {*} prevval prevval
 * @param {*} nextval nextval
 * @returns {void}
 * @hidden N
 */
scwin.Jongmok = function(prevval, nextval) {
    txb_jongmokName.setValue("");
    scwin.skw = "";
    dts_jongmok.UseFilter = "true";
    dts_jongmok.Filter();
    grd_jongmok.Redraw = "false";
    dts_jongmok.sort("+COM_ABBRV", 0);
    // dts_jongmok.sort(); // W-Craft 주석처리
    let cnt = 0;
    for (i = 1; i <= dts_jongmok.getRowCount(); i++) {
        let name = dts_jongmok.getCellData(i, "COM_ABBRV").substring(0, 1);
        if (name >= prevval && name < nextval) {
            cnt = i;
            break;
        }
    }
    grd_jongmok.Redraw = "true";
    dts_jongmok.setRowPosition(cnt + 11, 0);
    dts_jongmok.setRowPosition(cnt, 0);
    grd_jongmok.focus();
};

/**
 * @method
 * @name JongmokName
 * @description 종목명검색
 * @param {*} keyCode keyCode
 * @returns {void}
 * @hidden N
 */
scwin.JongmokName = function(keyCode) {
    // if(keyCode==13) on_close();
    grd_jongmok.Redraw = "false";
    dts_jongmok.sort("+COM_ABBRV", 0);
    // dts_jongmok.sort(); // W-Craft 주석처리
    let cnt = 0;
    const len = txb_jongmokName.getValue().length;
    const txtVal = txb_jongmokName.getValue().toUpperCase();
    for (i = 1; i <= dts_jongmok.getRowCount(); i++) {
        let name = dts_jongmok.getCellData(i, "COM_ABBRV").substring(0, len).toUpperCase();
        if (txtVal === name) {
            cnt = i;
            break;
        }
    }
    if (cnt === 0) {
        dts_jongmok.sort("+COM_NM", 0);
        // dts_jongmok.sort(); // W-Craft 주석처리
        for (i = 1; i <= dts_jongmok.getRowCount(); i++) {
            let name = dts_jongmok.getCellData(i, "COM_NM").substring(0, len).toUpperCase();
            if (txtVal === name) {
                cnt = i;
                break;
            }
        }
    }
    grd_jongmok.Redraw = "true";
    dts_jongmok.setRowPosition(cnt + 11, 0);
    dts_jongmok.setRowPosition(cnt, 0);
};

/**
 * @method
 * @name JongmokSearch
 * @description 종목명검색
 * @returns {void}
 * @hidden N
 */
scwin.JongmokSearch = function() {
    scwin.skw = txb_jongmokName.getValue();
    dts_jongmok.UseFilter = "true";
    dts_jongmok.Filter();
    dts_jongmok.setRowPosition(1, 0);
};

